-- Every song gets a 6-character share code (a–z, 0–9) for short links like
-- plai.delaneyprojects.xyz/s/abc123. Generated by the database whenever a track is inserted
-- without one, so syncs and sharing don't each need to remember.

CREATE OR REPLACE FUNCTION public.generate_short_id()
RETURNS text
LANGUAGE plpgsql
VOLATILE
SET search_path = public
AS $$
DECLARE
  alphabet constant text := 'abcdefghijklmnopqrstuvwxyz0123456789';
  candidate text;
  i int;
BEGIN
  LOOP
    candidate := '';
    FOR i IN 1..6 LOOP
      candidate := candidate || substr(alphabet, 1 + floor(random() * 36)::int, 1);
    END LOOP;
    EXIT WHEN NOT EXISTS (SELECT 1 FROM tracks WHERE short_id = candidate);
  END LOOP;
  RETURN candidate;
END;
$$;
REVOKE ALL ON FUNCTION public.generate_short_id() FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public.tracks_set_short_id()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public
AS $$
BEGIN
  IF NEW.short_id IS NULL THEN
    NEW.short_id := generate_short_id();
  END IF;
  RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION public.tracks_set_short_id() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS tracks_set_short_id ON public.tracks;
CREATE TRIGGER tracks_set_short_id BEFORE INSERT ON public.tracks
  FOR EACH ROW EXECUTE FUNCTION public.tracks_set_short_id();

-- Backfill songs that don't have a code yet
UPDATE public.tracks SET short_id = public.generate_short_id() WHERE short_id IS NULL;
